        assert_no_error(
            super::LANGUAGE_PHP,
            &sequential_heredocs("<?php\n", 250, "EOD"),
        );
        assert_no_error(
            super::LANGUAGE_PHP_ONLY,
            &sequential_heredocs("", 20, &long_tag),
