use tree_sitter::{Parser, Query, QueryCursor, StreamingIterator};

const ELEMENT_QUERY: &str = r"
(function_definition
  name: (name) @func_name) @function
(method_declaration
  name: (name) @method_name) @function
(class_declaration
  name: (name) @class_name) @class
(interface_declaration
  name: (name) @interface_name) @class
(trait_declaration
  name: (name) @trait_name) @class
(enum_declaration
  name: (name) @enum_name) @class
";

const CALL_QUERY: &str = r"
(function_call_expression
  function: [(name) (qualified_name (name))] @call)
(member_call_expression
  name: (name) @call)
(nullsafe_member_call_expression
  name: (name) @call)
(scoped_call_expression
  name: (name) @call)
";

const REFERENCE_QUERY: &str = r"
(named_type (name) @type_ref)
";

const IMPORT_QUERY: &str = r"
(namespace_use_declaration) @import_path
";

const DEFUSE_QUERY: &str = r"
(assignment_expression
  left: (variable_name (name) @write.assign))
(augmented_assignment_expression
  left: (variable_name (name) @writeread.assign))
(update_expression
  argument: (variable_name (name) @writeread.update))
(simple_parameter
  name: (variable_name (name) @write.param))
(variable_name (name) @read.usage)
";

fn main() {
    let lang: tree_sitter::Language = tree_sitter_php::LANGUAGE_PHP.into();
    for (n, q) in [
        ("ELEMENT", ELEMENT_QUERY),
        ("CALL", CALL_QUERY),
        ("REFERENCE", REFERENCE_QUERY),
        ("IMPORT", IMPORT_QUERY),
        ("DEFUSE", DEFUSE_QUERY),
    ] {
        match Query::new(&lang, q) {
            Ok(_) => println!("QUERY OK {n}"),
            Err(e) => println!("QUERY ERR {n}: {e:?}"),
        }
    }
    let src = "<?php\nnamespace App;\nuse Foo\\Bar;\ninterface I extends J, K {}\ntrait T {}\nenum E: string implements I { case A = 'a'; public function f(): void {} }\nclass Foo extends Bar implements A, B { public function m() { $x = 1; $x++; $this->bar(); self::baz(); strlen($x); \\ns\\g(); } }\nfunction top(int $z) { $z = 5; return $z; }\nclass Plain {}\n?>\n<h1>hi</h1>\n";
    let mut parser = Parser::new();
    parser.set_language(&lang).unwrap();
    let tree = parser.parse(src, None).unwrap();
    println!("HAS_ERROR={}", tree.root_node().has_error());
    let root = tree.root_node();
    for (n, q) in [("ELEMENT", ELEMENT_QUERY), ("CALL", CALL_QUERY), ("REFERENCE", REFERENCE_QUERY), ("IMPORT", IMPORT_QUERY), ("DEFUSE", DEFUSE_QUERY)] {
        let query = Query::new(&lang, q).unwrap();
        let mut cur = QueryCursor::new();
        let mut ms = cur.matches(&query, root, src.as_bytes());
        let mut out = Vec::new();
        while let Some(m) = ms.next() {
            for c in m.captures() {
                let name = query.capture_names()[c.index as usize];
                let t = &src[c.node.start_byte()..c.node.end_byte()];
                out.push(format!("{name}={:?}:{}", t, c.node.kind()));
            }
        }
        println!("{n}: {}", out.join(" | "));
    }
    let small = "class Foo extends Bar implements A, B {}\ninterface I extends J, K {}\nenum E: string implements I { }\ntrait T {}\nclass Plain {}";
    let t2 = parser.parse(small, None).unwrap();
    println!("SEXP: {}", t2.root_node().to_sexp());
}
